    form: [['Corta', 'My car is older than yours.', 'Mi carro es más viejo que el tuyo.'], ['Larga', 'This hotel is more expensive.', 'Este hotel es más caro.'], ['El más', 'She is the best in her class.', 'Ella es la mejor de su clase.']],
